    // `dart test/site/` is NOT a test invocation — dart treats
    // `test/site/` as a command name and exits 64 ("Could not find a
    // command named"), so the guards never ran and the step failed on
    // every CI run (validation CI red on 342423d0). The guards must
    // go through the `test` runner: `dart test test/site/`.
    expect(
      step,
      contains('dart test test/site/'),
      reason: 'site guards must run via the dart test runner',
    );
    // The forbidden shape is `dart test/site/` IN COMMAND POSITION
    // (after `run: ` or at a block-scalar line start). A blunt
    // substring scan also fires on a LEGIT multi-target run where the
    // chars form ACROSS the argument boundary — gh-1596's
    // installer-portability leg:
    // `run: dart test test/site/a_test.dart test/site/b_test.dart`
    // contains "...a_test.dart test/site/..." → "dart test/site/"
    // mid-line. Anchor to the command position the gh-1476 bug
    // actually shipped (validation CI red on 342423d0).
    final badCommandShapes = <String, RegExp>{
      'inline run: dart test/site/': RegExp(r'run: *dart test/site/'),
      'block-scalar line dart test/site/': RegExp(
        r'^ *dart test/site/',
        multiLine: true,
      ),
    };
    // Guard stays honest (#1100 pattern): both bug shapes match.
    badCommandShapes.forEach((shape, pattern) {
      expect(
        pattern.hasMatch('run: dart test/site/'),
        isTrue,
        reason: '$shape must be caught by the guard',
      );
      expect(
        pattern.hasMatch('  dart test/site/'),
        isTrue,
        reason: '$shape must be caught by the guard',
      );
      expect(
        pattern.hasMatch(
          'run: dart test test/site/setup_test.dart '
          'test/site/installer_test.dart',
        ),
        isFalse,
        reason: '$shape must not fire on a multi-target argument '
            'boundary — that is a valid `dart test` invocation',
      );
    });
    badCommandShapes.forEach((shape, pattern) {
      expect(
        step,
        isNot(contains(pattern)),
        reason: '`dart test/site/` in command position is not a test '
            'invocation — dart treats it as a command name and exits '
            '64 ($shape)',
      );
    });
  },
);

